practice.solution:
const product = {
  title: "Lamp",
  price: 25,
  dimensions: { width: 30, height: 45 },
};

function formatProduct({ title, price }) {
  return `${title}: $${price}`;
}

const { title: productName, price, currency = "USD" } = product;
const { dimensions: { width } } = product;

console.log(`${productName} costs ${price} ${currency}`);
console.log(`width: ${width}`);
console.log(formatProduct(product));

