practice.solution:
const baseConfig = { host: "localhost", port: 8080, retries: 3 };
const overrides = { port: 3000 };
const coreTags = ["core"];
const uiTags = ["ui"];
const apiTags = ["api", "docs"];
const team = { name: "web", members: ["ana", "ben"] };

function volume(length, width, height) {
  return length * width * height;
}

const merged = { ...baseConfig, ...overrides };
console.log(JSON.stringify(merged));

const debugConfig = { ...merged, debug: true };
console.log(JSON.stringify(debugConfig));

const allTags = [...coreTags, ...uiTags, ...apiTags];
console.log(allTags.join(", "));

const box = [2, 3, 4];
console.log(`volume: ${volume(...box)}`);

const copy = { ...team };
copy.members.push("eve");
console.log(`original members: ${team.members.join(", ")}`);

