practice.solution:
const queue = ["ana", "ben", "cal"];
const order = { id: 7, item: "lamp", qty: 2 };

function maxOf(label, ...values) {
  return `${label}: ${Math.max(...values)}`;
}

console.log(maxOf("temps", 18, 25, 21));
console.log(maxOf("scores", 7, 3));

const [head, ...tail] = queue;
console.log(`next: ${head}`);
console.log(`waiting: ${tail.join(", ")}`);

const { id, ...details } = order;
console.log(`Order ${id}: ${JSON.stringify(details)}`);
